from collections import deque


def minStepsWithPortals(grid):
    rows, cols = len(grid), len(grid[0])
    first = {}
    twin = {}
    for r in range(rows):
        for c in range(cols):
            v = grid[r][c]
            if v > 0:
                if v in first:
                    twin[(r, c)] = first[v]
                    twin[first[v]] = (r, c)
                else:
                    first[v] = (r, c)
    dist = [[-1] * cols for _ in range(rows)]
    dist[0][0] = 0
    q = deque([(0, 0)])
    while q:
        r, c = q.popleft()
        if r == rows - 1 and c == cols - 1:
            return dist[r][c]
        nxt = [(r + dr, c + dc) for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1))
               if 0 <= r + dr < rows and 0 <= c + dc < cols and grid[r + dr][c + dc] != -1]
        if (r, c) in twin:
            nxt.append(twin[(r, c)])
        for nr, nc in nxt:
            if dist[nr][nc] == -1:
                dist[nr][nc] = dist[r][c] + 1
                q.append((nr, nc))
    return -1
